/* Every NT system service, as the one-line stub Windows' own ntdll has for it
 * (docs/abi/windows.md W1).
 *
 * Generated by the preprocessor from kernel/abi/nt_services.def, the file the
 * kernel's table is checked against, so the number in each stub is the number
 * the kernel answers to - the only agreement a system call needs, and here it
 * cannot drift. A service the kernel does not implement yet still has its stub
 * and its export: the call reaches the kernel and is answered
 * STATUS_NOT_IMPLEMENTED and counted there, as an unassigned Linux number is,
 * rather than failing to link in the program that names it.
 *
 * Windows' convention, kept exactly: the arguments as the caller placed them -
 * rcx, rdx, r8, r9, then the stack from rsp+0x28 - with rcx moved to r10
 * because `syscall` overwrites rcx with the return address. */

#define NT(nr, name, args, state, step) \
    .text ; \
    .globl name ; \
    .p2align 4 ; \
name: ; \
    mov %rcx, %r10 ; \
    mov $nr, %eax ; \
    syscall ; \
    ret ; \
    .section .drectve ; \
    .ascii " -export:" #name ; \
    .text ;

#include "nt_services.def"

/* The stubs ntdll's loader binds a missing import to (start.c, W2): stub k is
 * at vibeos_nt_stub_table + 16 * k and calls vibeos_nt_unimplemented(k), which
 * names the import it stands for and ends the process. Reached by the
 * program's own call through its import table, so the stack is a callee's and
 * a jump is all it takes; k is the first argument, in ecx. Sixteen bytes each,
 * whatever the jump assembles to, so the loader can find stub k by arithmetic. */
    .text
    .p2align 4
    .globl vibeos_nt_stub_table
vibeos_nt_stub_table:
    .set vibeos_stub_k, 0
    .rept 2048
    .p2align 4
    mov $vibeos_stub_k, %ecx
    jmp vibeos_nt_unimplemented
    .set vibeos_stub_k, vibeos_stub_k + 1
    .endr
